BEGIN
  INSERT INTO public.studios (id, owner_profile_id, slug, name, description, location, geo_lat, geo_lng, hourly_rate_paise, rating, review_count, verified_gold, console_type, services, amenities, cancellation_policy, operating_hours, image_url, images, created_at)
  SELECT r.id, r.owner_profile_id, r.slug, r.name, r.description, r.location, r.geo_lat, r.geo_lng, r.hourly_rate_paise, r.rating, r.review_count, r.verified_gold, r.console_type, r.services, r.amenities, r.cancellation_policy, r.operating_hours, r.image_url, r.images, r.created_at FROM jsonb_to_recordset(payload) AS r(id uuid, owner_profile_id uuid, slug text, name text, description text, location text, geo_lat double precision, geo_lng double precision, hourly_rate_paise bigint, rating numeric, review_count int, verified_gold boolean, console_type text, services text[], amenities text[], cancellation_policy text, operating_hours text, image_url text, images text[], created_at timestamptz)
  ON CONFLICT (id) DO UPDATE SET owner_profile_id = EXCLUDED.owner_profile_id, slug = EXCLUDED.slug, name = EXCLUDED.name, description = EXCLUDED.description, location = EXCLUDED.location, geo_lat = EXCLUDED.geo_lat, geo_lng = EXCLUDED.geo_lng, hourly_rate_paise = EXCLUDED.hourly_rate_paise, rating = EXCLUDED.rating, review_count = EXCLUDED.review_count, verified_gold = EXCLUDED.verified_gold, console_type = EXCLUDED.console_type, services = EXCLUDED.services, amenities = EXCLUDED.amenities, cancellation_policy = EXCLUDED.cancellation_policy, operating_hours = EXCLUDED.operating_hours, image_url = EXCLUDED.image_url, images = EXCLUDED.images, created_at = EXCLUDED.created_at;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, owner_profile_id uuid, slug text, name text, description text, location text, geo_lat double precision, geo_lng double precision, hourly_rate_paise bigint, rating numeric, review_count int, verified_gold boolean, console_type text, services text[], amenities text[], cancellation_policy text, operating_hours text, image_url text, images text[], created_at timestamptz) JOIN public.studios t ON t.id = r.id
      WHERE (t.id, t.owner_profile_id, t.slug, t.name, t.description, t.location, t.geo_lat, t.geo_lng, t.hourly_rate_paise, t.rating, t.review_count, t.verified_gold, t.console_type, t.services, t.amenities, t.cancellation_policy, t.operating_hours, t.image_url, t.images) IS NOT DISTINCT FROM (r.id, r.owner_profile_id, r.slug, r.name, r.description, r.location, r.geo_lat, r.geo_lng, r.hourly_rate_paise, r.rating, r.review_count, r.verified_gold, r.console_type, r.services, r.amenities, r.cancellation_policy, r.operating_hours, r.image_url, r.images))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'studios import: stored rows differ from the payload';
  END IF;
END
$import$;

