  payload jsonb := $json$[{"id":"2980ca81-3ed7-5083-9701-6e839d095d93","studio_id":"29833230-3ca8-58e3-b0c2-f87756c18008","name":"Studio A — Live Room","capacity":10,"hourly_rate_paise":450000,"amenities":["dolby_atmos","live_room"],"sort_order":0},{"id":"5fa6f330-452e-521e-a469-d85a92e0401c","studio_id":"29833230-3ca8-58e3-b0c2-f87756c18008","name":"Vocal Booth B","capacity":2,"hourly_rate_paise":220000,"amenities":["vocal_booth"],"sort_order":1},{"id":"e7eddf90-bf72-50e6-8311-1c17c69ca1a2","studio_id":"29833230-3ca8-58e3-b0c2-f87756c18008","name":"Rehearsal Room C","capacity":6,"hourly_rate_paise":150000,"amenities":["rehearsal_room"],"sort_order":2},{"id":"7db10a88-f1e6-5d52-97f5-182254aa8d77","studio_id":"3b0324b2-a7e7-5ba3-b3fc-a64a0b87b348","name":"Tracking Room 1","capacity":12,"hourly_rate_paise":800000,"amenities":["live_room","resident_engineers"],"sort_order":0},{"id":"415d2f7f-3ffb-5e20-a027-73272dd219ae","studio_id":"3b0324b2-a7e7-5ba3-b3fc-a64a0b87b348","name":"Dolby Atmos Mixing Suite","capacity":4,"hourly_rate_paise":650000,"amenities":["dolby_atmos"],"sort_order":1}]$json$;
BEGIN
  INSERT INTO public.studio_rooms (id, studio_id, name, capacity, hourly_rate_paise, amenities, sort_order)
  SELECT r.id, r.studio_id, r.name, r.capacity, r.hourly_rate_paise, r.amenities, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, studio_id uuid, name text, capacity int, hourly_rate_paise bigint, amenities text[], sort_order int)
  ON CONFLICT (id) DO UPDATE SET studio_id = EXCLUDED.studio_id, name = EXCLUDED.name, capacity = EXCLUDED.capacity, hourly_rate_paise = EXCLUDED.hourly_rate_paise, amenities = EXCLUDED.amenities, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, studio_id uuid, name text, capacity int, hourly_rate_paise bigint, amenities text[], sort_order int) JOIN public.studio_rooms t ON t.id = r.id
      WHERE (t.id, t.studio_id, t.name, t.capacity, t.hourly_rate_paise, t.amenities, t.sort_order) IS NOT DISTINCT FROM (r.id, r.studio_id, r.name, r.capacity, r.hourly_rate_paise, r.amenities, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'studio_rooms import: stored rows differ from the payload';
  END IF;
END
$import$;

-- studio_equipment (16 rows)
