BEGIN
  INSERT INTO public.studio_equipment (id, studio_id, name, category, quantity, included, sort_order)
  SELECT r.id, r.studio_id, r.name, r.category, r.quantity, r.included, r.sort_order FROM jsonb_to_recordset(payload) AS r(id uuid, studio_id uuid, name text, category text, quantity int, included boolean, sort_order int)
  ON CONFLICT (id) DO UPDATE SET studio_id = EXCLUDED.studio_id, name = EXCLUDED.name, category = EXCLUDED.category, quantity = EXCLUDED.quantity, included = EXCLUDED.included, sort_order = EXCLUDED.sort_order;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, studio_id uuid, name text, category text, quantity int, included boolean, sort_order int) JOIN public.studio_equipment t ON t.id = r.id
      WHERE (t.id, t.studio_id, t.name, t.category, t.quantity, t.included, t.sort_order) IS NOT DISTINCT FROM (r.id, r.studio_id, r.name, r.category, r.quantity, r.included, r.sort_order))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'studio_equipment import: stored rows differ from the payload';
  END IF;
END
