BEGIN
  INSERT INTO public.feed_posts (id, author_profile_id, post_type, body, media_urls, audio_url, likes_count, comments_count, created_at)
  SELECT r.id, r.author_profile_id, r.post_type, r.body, r.media_urls, r.audio_url, r.likes_count, r.comments_count, r.created_at FROM jsonb_to_recordset(payload) AS r(id uuid, author_profile_id uuid, post_type text, body text, media_urls text[], audio_url text, likes_count int, comments_count int, created_at timestamptz)
  ON CONFLICT (id) DO UPDATE SET author_profile_id = EXCLUDED.author_profile_id, post_type = EXCLUDED.post_type, body = EXCLUDED.body, media_urls = EXCLUDED.media_urls, audio_url = EXCLUDED.audio_url, likes_count = EXCLUDED.likes_count, comments_count = EXCLUDED.comments_count, created_at = EXCLUDED.created_at;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(id uuid, author_profile_id uuid, post_type text, body text, media_urls text[], audio_url text, likes_count int, comments_count int, created_at timestamptz) JOIN public.feed_posts t ON t.id = r.id
      WHERE (t.id, t.author_profile_id, t.post_type, t.body, t.media_urls, t.audio_url, t.likes_count, t.comments_count) IS NOT DISTINCT FROM (r.id, r.author_profile_id, r.post_type, r.body, r.media_urls, r.audio_url, r.likes_count, r.comments_count))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'feed_posts import: stored rows differ from the payload';
  END IF;
END
$import$;

