-- cms_pages (9 rows)
DO $import$
DECLARE
  payload jsonb := $json$[{"slug":"about","route":"/about","title":"About MusicLinkd","status":"published","content":"MusicLinkd was built to make it easier for independent artists, studios, and venues across India to find and book each other.","seo_description":"Learn about MusicLinkd's mission to connect India's music community.","updated_at":"2026-08-01T09:00:00Z"},{"slug":"blog","route":"/blog","title":"MusicLinkd Blog","status":"draft","content":"Stories from India's independent music scene — coming soon.","seo_description":"News and stories from the MusicLinkd community.","updated_at":"2026-07-18T09:00:00Z"},{"slug":"careers","route":"/careers","title":"Careers at MusicLinkd","status":"draft","content":"We're not actively hiring right now, but we're always open to hearing from people passionate about music and technology.","seo_description":"Careers and open roles at MusicLinkd.","updated_at":"2026-07-20T09:00:00Z"},{"slug":"contact","route":"/contact","title":"Contact MusicLinkd","status":"published","content":"Reach the MusicLinkd team for support, partnerships, or press inquiries.","seo_description":"Get in touch with the MusicLinkd team.","updated_at":"2026-08-13T09:00:00Z"},{"slug":"home","route":"/","title":"MusicLinkd — Find your next collaborator","status":"published","content":"MusicLinkd connects singers, musicians, producers, studios, and venues across India for collaboration, booking, and hire.","seo_description":"MusicLinkd is India's marketplace for music talent, studios, and collaboration.","updated_at":"2026-08-01T09:00:00Z"},{"slug":"legal-cookies","route":"/legal/cookies","title":"Cookie Policy","status":"published","content":"This Cookie Policy explains how MusicLinkd uses cookies and similar technologies.","seo_description":"MusicLinkd cookie policy.","updated_at":"2026-06-01T09:00:00Z"},{"slug":"legal-privacy","route":"/legal/privacy","title":"Privacy Policy","status":"published","content":"This Privacy Policy explains how MusicLinkd collects, uses, and protects your information.","seo_description":"MusicLinkd privacy policy.","updated_at":"2026-06-01T09:00:00Z"},{"slug":"legal-terms","route":"/legal/terms","title":"Terms of Service","status":"published","content":"These Terms of Service govern your use of MusicLinkd.","seo_description":"MusicLinkd terms of service.","updated_at":"2026-06-01T09:00:00Z"},{"slug":"pricing","route":"/pricing","title":"Pricing","status":"published","content":"Free to join. Studios and businesses can upgrade to a Pro plan for advanced booking and analytics tools.","seo_description":"MusicLinkd pricing plans for talent, studios, and businesses.","updated_at":"2026-08-01T09:00:00Z"}]$json$;
BEGIN
  INSERT INTO public.cms_pages (slug, route, title, status, content, seo_description, updated_at)
  SELECT r.slug, r.route, r.title, r.status, r.content, r.seo_description, r.updated_at FROM jsonb_to_recordset(payload) AS r(slug text, route text, title text, status text, content text, seo_description text, updated_at timestamptz)
  ON CONFLICT (slug) DO UPDATE SET route = EXCLUDED.route, title = EXCLUDED.title, status = EXCLUDED.status, content = EXCLUDED.content, seo_description = EXCLUDED.seo_description, updated_at = EXCLUDED.updated_at;

  IF (SELECT count(*) FROM jsonb_to_recordset(payload) AS r(slug text, route text, title text, status text, content text, seo_description text, updated_at timestamptz) JOIN public.cms_pages t ON t.slug = r.slug
      WHERE (t.slug, t.route, t.title, t.status, t.content, t.seo_description) IS NOT DISTINCT FROM (r.slug, r.route, r.title, r.status, r.content, r.seo_description))
     <> jsonb_array_length(payload) THEN
    RAISE EXCEPTION 'cms_pages import: stored rows differ from the payload';
  END IF;
END
$import$;
